 // วิธีวัดค่า box.top / box.height ของแต่ละข้อ (ทำครั้งเดียวตอนเตรียมข้อมูล):
 // 1) เปิดรูปสัญญาต้นฉบับ (650x912px)
 // 2) วาดเส้นกริดแนวนอนทุก 5% ของความสูงทับบนรูป (ใช้ PIL หรือโปรแกรมแต่งภาพใดก็ได้)
 // 3) ไล่ดูว่าข้อความแต่ละ "ข้อ" เริ่มต้น (top) และมีความสูง (height) กี่ % ของรูป
 // 4) กรอกค่าลง box: { top: "xx%", height: "yy%" } — ถ้าเปลี่ยนรูปสัญญาใหม่
 //    ต้องวัดค่านี้ใหม่ทุกครั้ง เพราะตำแหน่งข้อความจะไม่เหมือนเดิม
 
 // สีและป้ายกำกับของแต่ละระดับความเสี่ยง ใช้ร่วมกันทั้งกรอบไฮไลท์บนรูป
 // และแถบสีบน card รายการข้อสัญญาด้านล่าง
 const LEVEL_META = {
   green: { label: "ปลอดภัย", color: "#1E5E3A", bg: "#EAF5EF", border: "#2D6A4F" },
   yellow: { label: "ควรระวัง", color: "#9E6B00", bg: "#FFF8E7", border: "#B8860B" },
   red: { label: "อันตราย", color: "#B81D1D", bg: "#FDF2F2", border: "#C1272D" },
 };
 
 // สรุประดับความเสี่ยงโดยรวมของสัญญา จาก array ข้อสัญญาทั้งหมด (เอาระดับที่
 // แย่ที่สุดที่พบเป็นตัวตัดสิน: มีข้อ "แดง" ข้อเดียวก็ถือว่าทั้งฉบับความเสี่ยงสูง)
 function overallRisk(clauses) {
   if (clauses.some((c) => c.level === "red")) return "red";
   if (clauses.some((c) => c.level === "yellow")) return "yellow";
   return "green";
 }
 
 // ---------- ตราปั๊มไฟสัญญาณ (Signature element) — เพิ่มโดยรอบปรับดีไซน์ ----------
 // วงกลมสไตล์ "ตราประทับ" เอกสารราชการ เอียงเล็กน้อยเหมือนปั๊มด้วยมือ มีไฟ
 // สัญญาณ (จุดสี เขียว/เหลือง/แดง) กระพริบเบาๆ อยู่ข้างในเหนือป้ายระดับความ
 // เสี่ยง ใช้แทนที่ badge สีธรรมดา เพื่อให้เชื่อมโยงกับความรู้สึก "เอกสาร/
 // สัญญาที่ผ่านการตรวจแล้ว" — ใช้ร่วมกันทั้งหน้าแรก (step 0, บนกระดาษจำลอง)
 // และหน้าผลลัพธ์ (step 2, ตัวใหญ่กลางหน้า) ให้ดีไซน์ไปทิศทางเดียวกัน
 function RiskSeal({ level, size = 96 }) {
   const meta = LEVEL_META[level];
   return (
     <div
       className="tc-seal"
       style={{
         width: size,
         height: size,
         borderRadius: "50%",
         border: `3px solid ${meta.border}`,
         display: "flex",
         alignItems: "center",
         justifyContent: "center",
         position: "relative",
         transform: "rotate(-6deg)",
         boxShadow: `0 0 0 3px ${meta.bg}, 2px 3px 6px rgba(0,0,0,0.18)`,
         flexShrink: 0,
         background: "#FFFDF8",
       }}
     >
       <div
         style={{
           position: "absolute",
           inset: 6,
           borderRadius: "50%",
           border: `1px dashed ${meta.border}`,
           opacity: 0.5,
         }}
       />
       <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
         <div
           className="tc-seal-light"
           style={{
             width: size * 0.22,
             height: size * 0.22,
             borderRadius: "50%",
             background: meta.border,
             boxShadow: `0 0 6px ${meta.border}99`,
           }}
         />
         <span
           style={{
             fontFamily: "'Noto Serif Thai', serif",
             fontWeight: 800,
             fontSize: size * 0.155,
             color: meta.color,
             letterSpacing: 0.5,
             whiteSpace: "nowrap",
           }}
         >
           {meta.label}
         </span>
       </div>
     </div>
   );
 }
 
