 // คะแนนรวมสูงสุดที่เป็นไปได้ = 2+3+3+2 = 10 ใช้อ้างอิงตอนคำนวณ threshold
 // คืนค่า key ของ LEVEL_META ("green" | "yellow" | "red") จากคะแนนรวม
 function getCriminalRiskLevel(totalScore) {
   if (totalScore <= 2) return "green";
   if (totalScore <= 5) return "yellow";
   return "red";
 }
 
