 // กรอบพิกัด (ละติจูด/ลองจิจูด) จริงของประเทศไทย คำนวณจาก min/max ของ
 // PROVINCE_GEO ทั้งหมด (บวก padding ~2% กันรูปทรงชิดขอบ viewBox เกินไป)
 const MAP_LAT_LON_BOUNDS = { lonMin: 97.1, lonMax: 105.9, latMin: 5.4, latMax: 20.7 };
 // ขนาด viewBox ของ SVG แผนที่ (สัดส่วนสอดคล้องกับกรอบพิกัดด้านบน)
 const MAP_VIEW_SIZE = { width: 400, height: 714 };
 
 // แปลงพิกัด (lat, lon) เป็นตำแหน่ง {x, y} บน SVG ตาม MAP_LAT_LON_BOUNDS/MAP_VIEW_SIZE
 function projectLatLon(lat, lon) {
   const { lonMin, lonMax, latMin, latMax } = MAP_LAT_LON_BOUNDS;
   const x = ((lon - lonMin) / (lonMax - lonMin)) * MAP_VIEW_SIZE.width;
   const y = ((latMax - lat) / (latMax - latMin)) * MAP_VIEW_SIZE.height;
   return { x, y };
 }
 
 // ดึง array ของ "polygon" ออกจาก feature เดียว ไม่ว่า feature นั้นจะเป็น
 // Polygon ธรรมดา (g:"P", มีรูปทรงเดียว) หรือ MultiPolygon (g:"M", มีหลาย
 // รูปทรง เช่น จังหวัดที่มีเกาะ) ผลลัพธ์เป็น array-of-polygon เสมอ ทำให้โค้ด
 // ที่ไล่วนรูปทรงจังหวัด (pathForProvince/bboxForProvince/centroidForProvince
 // ด้านล่าง) เขียนลูปเดียวกันได้โดยไม่ต้องเช็ค g ซ้ำทุกจุด
 // (เดิมทั้ง 3 ฟังก์ชันนี้เขียนเงื่อนไข "feature.g === 'M' ? feature.c :
 // [feature.c]" ซ้ำกันเป๊ะๆ คนละที่ — รวมมาไว้ที่นี่ที่เดียว)
 function getPolygons(feature) {
   return feature.g === "M" ? feature.c : [feature.c];
 }
 
 // สร้าง SVG path "d" จากรูปทรงจังหวัด 1 จังหวัด (รองรับทั้ง Polygon และ
 // MultiPolygon — MultiPolygon คือจังหวัดที่มีเกาะ/แผ่นดินแยกส่วน เช่น ภูเก็ต,
 // ตราด, สุราษฎร์ธานี) แต่ละ ring ผ่าน projectLatLon() แล้วต่อเป็น "M..L..Z"
 function pathForProvince(feature) {
   const polygons = getPolygons(feature);
   let d = "";
   for (const polygon of polygons) {
     for (const ring of polygon) {
       const pts = ring.map(([lon, lat]) => {
         const { x, y } = projectLatLon(lat, lon);
         return `${x.toFixed(1)},${y.toFixed(1)}`;
       });
       d += `M ${pts.join(" L ")} Z `;
     }
   }
   return d.trim();
 }
 
 // คำนวณกรอบสี่เหลี่ยม (bounding box) ของจังหวัด 1 จังหวัด ในพิกัด SVG
 // (หลังผ่าน projectLatLon แล้ว) ใช้สำหรับคำนวณ transform ตอนซูมโฟกัส
 function bboxForProvince(feature) {
   const polygons = getPolygons(feature);
   let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
   for (const polygon of polygons) {
     for (const ring of polygon) {
       for (const [lon, lat] of ring) {
         const { x, y } = projectLatLon(lat, lon);
         if (x < minX) minX = x;
         if (x > maxX) maxX = x;
         if (y < minY) minY = y;
         if (y > maxY) maxY = y;
       }
     }
   }
   return { minX, maxX, minY, maxY, cx: (minX + maxX) / 2, cy: (minY + maxY) / 2 };
 }
 
 // คำนวณจุดศูนย์กลางมวล (centroid) ของ ring เดียว ด้วยสูตร shoelace — แม่นยำ
 // กว่าแค่เฉลี่ยพิกัด minX/maxX (bbox center) เพราะ bbox center อาจตกอยู่นอก
 // รูปทรงจริงได้ถ้าจังหวัดมีรูปร่างเว้า/โค้งเยอะ (พบบ่อยกับจังหวัดไทย)
 function ringCentroid(points) {
   let area = 0, cx = 0, cy = 0;
   for (let i = 0; i < points.length; i++) {
     const [x1, y1] = points[i];
     const [x2, y2] = points[(i + 1) % points.length];
     const cross = x1 * y2 - x2 * y1;
     area += cross;
     cx += (x1 + x2) * cross;
     cy += (y1 + y2) * cross;
   }
   area /= 2;
   if (Math.abs(area) < 1e-6) {
     const n = points.length || 1;
     const sx = points.reduce((s, p) => s + p[0], 0);
     const sy = points.reduce((s, p) => s + p[1], 0);
     return { x: sx / n, y: sy / n, area: 0 };
   }
   return { x: cx / (6 * area), y: cy / (6 * area), area: Math.abs(area) };
 }
 
 // จุดศูนย์กลาง "ที่ใช้วางป้าย/เลขอันดับ" ของจังหวัด — เลือก ring นอกสุดที่
 // มีพื้นที่มากที่สุด (แผ่นดินผืนหลัก ไม่ใช่เกาะเล็กๆ ถ้าเป็น MultiPolygon)
 // แล้วหา centroid ของ ring นั้น รับประกันว่าจุดจะอยู่ในเนื้อจังหวัดจริงเสมอ
 function centroidForProvince(feature) {
   const polygons = getPolygons(feature);
   let best = null;
   for (const polygon of polygons) {
     const ring = polygon[0]; // ring แรก = เส้นขอบนอก (ไม่สนใจรู/holes)
     const projected = ring.map(([lon, lat]) => {
       const { x, y } = projectLatLon(lat, lon);
       return [x, y];
     });
     const result = ringCentroid(projected);
     if (!best || result.area > best.area) best = result;
   }
   if (!best) return { x: 0, y: 0 };
   return { x: best.x, y: best.y };
 }
 
 
